  "claims": [
    {
      "claim": "Structures of inequality and domination might be or become axes of political conflict and struggle, a possibility not fully confronted by Wallace-Wells.",
      "claim_type": "author_position",
      "supporting_excerpt": "Still, even Wallace-Wells never quite confronts the possibility that, beyond being vectors of unequal suffering or sources of war and disorder, these structures of inequality and domination might be or become axes of political conflict and struggle.",
      "support_kind": "direct",
      "confidence": 1.0
    },
    {
      "claim": "In eighteenth-century North America, the term out of doors was frequently used to describe people acting outside of legal representative institutions through mobs, crowds, or extralegal associations.",
      "claim_type": "historical_context",
      "supporting_excerpt": "In eighteenth-century North America, the term “out of doors” was frequently used to characterize the people of the British colonies, and then of the postrevolutionary United States, acting “outside of the legal representative institutions” by which they were governed, sometimes in mobs and crowds and sometimes through “extralegal associations.”",
      "support_kind": "direct",
      "confidence": 1.0
    }
  ],
  "definitions": [
    {
      "term": "out of doors",
      "definition": "A term used in eighteenth-century North America to characterize the people acting outside of the legal representative institutions by which they were governed, sometimes in mobs and crowds and sometimes through extralegal associations."
    }
  ],
  "distinctions": [],
  "references_to_other_sections": [],
  "unresolved_context": [],
  "must_not_be_lost": [
    "The connection between the literal meaning of out of doors and its figurative use for action and association outside of official channels."
  ]
}

